-- =====================================================================
--  Werkstatt — Migration auf 14.0.0: Konten, Rollen und Standorte
--
--  Vorher muss gelaufen sein: db/migration_13.0.0.sql (Kategorie-Namen
--  in der Datenbank).
--
--  Bitte zuerst auf einem Neon-Branch testen (Neon → Branches → Create
--  branch), dann auf main.
--
--  Einmal komplett im SQL-Editor von Neon ausführen. Ganz unten erscheint
--  der Einrichtungscode für das Konto „Hauke“ (Gesamt-Admin). Danach:
--  Data API → "Refresh schema cache".
--
--  Was passiert:
--  - Neue Tabelle standort; alle vorhandenen Daten gehören zum ersten
--    Standort „RSZ Schwerin“ (Spalte standort_id). Der Briefkopf der
--    Rechnungen zieht aus der App in diese Tabelle.
--  - Neue Tabellen konto, konto_rolle, einladung, sitzung, fehlversuch.
--    Anmeldung mit Name + PIN; die App schickt den Sitzungsschlüssel in
--    der Kopfzeile X-Sitzung, den Standort in X-Standort.
--  - Rollen je Standort: manager, trainer, geschaeftsstelle, sportler;
--    dazu der Gesamt-Admin. Alle Zugriffsregeln und Rechte neu.
--  - Sportler-Namen, Kategorien, Tags und Rechnungsnummern sind nur noch
--    je Standort eindeutig.
--  - Jeder Code trägt das Kürzel des Standorts (Schwerin: SN). Vorhandene
--    Codes werden umbenannt: B-101 → SN-B-101, L-102 → SN-L-102,
--    BR-01 → SN-BR-01. Buchungen, Tickets, Tags, Packlisten ziehen mit.
--  - Die alte Anmeldung aus 3.0.0 (Rolle authenticated, ist_trainer,
--    zugang_anfragen) wird entfernt. Die Tabellen trainer und person
--    bleiben mit ihren Daten stehen, sind aber nicht mehr lesbar.
--  Vorhandene Daten bleiben erhalten.
-- =====================================================================

begin;

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------
--  1. Alte Zugriffsregeln und die Anmeldung aus 3.0.0 entfernen
-- ---------------------------------------------------------------------
do $$
declare
  p record;
begin
  for p in select schemaname, tablename, policyname from pg_policies where schemaname = 'public' loop
    execute format('drop policy %I on %I.%I', p.policyname, p.schemaname, p.tablename);
  end loop;
end $$;

drop function if exists zugang_anfragen(text);
drop function if exists ist_trainer();
revoke all on all tables in schema public from authenticated;
revoke all on all sequences in schema public from authenticated;
revoke execute on all functions in schema public from authenticated;
revoke usage on schema public from authenticated;

-- ---------------------------------------------------------------------
--  2. Standorte und Konten
-- ---------------------------------------------------------------------
-- Standorte: jeder hat eigene Daten (Lager, Sportler, Räder, Tickets,
-- Rechnungen) und einen eigenen Briefkopf, den die Geschäftsstelle pflegt.
create table standort (
  id                 bigint generated always as identity primary key,
  name               text not null unique check (trim(name) <> ''),
  kuerzel            text not null unique check (kuerzel ~ '^[A-Z]{2,3}$'),   -- vor jedem Code: SN-B-101, SN-BR-01
  aktiv              boolean not null default true,
  angelegt           timestamptz not null default now(),
  rg_empfaenger      text,      -- Zahlungsempfänger / Kontoinhaber (auch Gruß und GiroCode)
  rg_absender        text,      -- Absenderzeile über der Anschrift
  rg_kopf            text,      -- Kontaktblock rechts oben, Zeilen; die erste fett
  rg_fuss            text,      -- Fußzeile: Spalten durch eine Leerzeile getrennt
  rg_text            text,      -- Einleitungssatz über den Posten
  iban               text,
  bic                text,
  bank               text,
  zahlungsziel_tage  integer not null default 14 check (zahlungsziel_tage between 0 and 90),
  logo               text check (logo is null or length(logo) <= 400000),        -- Bild als data:-URL
  fuss_logo          text check (fuss_logo is null or length(fuss_logo) <= 400000)
);

-- Erster Standort mit dem bisherigen Briefkopf (IBAN/BIC/Bank trägt die
-- Geschäftsstelle in der App ein).
insert into standort (name, kuerzel, rg_empfaenger, rg_absender, rg_kopf, rg_fuss, rg_text, zahlungsziel_tage, logo, fuss_logo)
values ('RSZ Schwerin',
        'SN',
        'Radsportverband Mecklenburg-Vorpommern e.V.',
        'Radsportverband Mecklenburg-Vorpommern e.V., Wittenburger Str. 120a, 19059 Schwerin',
        E'RADSPORTVERBAND\nMecklenburg-Vorpommern e.V.\nWittenburger Str. 120a · 19059 Schwerin\nMo–Fr 09.00–15.30 Uhr\nTel. 0385 / 74 51 363 · Fax 0385 / 73 42 83\ngeschaeftsstelle@radsport-mv.de',
        E'RADSPORTVERBAND\nMecklenburg-Vorpommern e.V.\nwww.radsport-mv.de\n\nPräsident\nTom Rogall, Dassow\n+49 176 34219523\n\nVizepräsident W. u. F.\nJörg Richter, Wismar\n+49 172 3995155\n\nFinanzamt Schwerin\nSteuernummer:\n090/142/00980',
        'Für Werkstattleistungen und Material der Werkstatt im Radsportzentrum berechnen wir Ihnen:',
        14,
        'data:image/jpeg' || chr(59) || 'base64,',
        'data:image/jpeg' || chr(59) || 'base64,');

-- ---------------------------------------------------------------------
--  Konten und Anmeldung (PIN). Von außen nicht lesbar — nur über die
--  Funktionen anmelden, einladung_einloesen, konten_liste usw.
-- ---------------------------------------------------------------------
create table konto (
  id            bigint generated always as identity primary key,
  name          text not null check (trim(name) <> ''),
  pin_hash      text,                         -- bcrypt; leer = Einladung offen
  fehlversuche  integer not null default 0,
  gesperrt_bis  timestamptz,
  gesamt_admin  boolean not null default false,
  sportler_id   bigint unique references sportler (id),   -- nur Sportler-Konten
  aktiv         boolean not null default true,
  angelegt      timestamptz not null default now(),
  zuletzt       timestamptz
);

-- Rolle je Standort: manager | trainer | geschaeftsstelle | sportler
create table konto_rolle (
  konto_id     bigint not null references konto (id) on delete cascade,
  standort_id  bigint not null references standort (id),
  rolle        text not null check (rolle in ('manager', 'trainer', 'geschaeftsstelle', 'sportler')),
  primary key (konto_id, standort_id)
);

-- Einladungscode (nur als Prüfsumme gespeichert), 7 Tage gültig, einmal.
create table einladung (
  code_hash     text primary key,
  konto_id      bigint not null unique references konto (id) on delete cascade,
  gueltig_bis   timestamptz not null,
  angelegt      timestamptz not null default now(),
  angelegt_von  text
);

-- Angemeldete Geräte (Schlüssel nur als Prüfsumme gespeichert).
create table sitzung (
  token_hash   text primary key,
  konto_id     bigint not null references konto (id) on delete cascade,
  angelegt     timestamptz not null default now(),
  gueltig_bis  timestamptz not null,
  geraet       text not null default 'handy' check (geraet in ('handy', 'werkstatt'))
);
create index sitzung_konto on sitzung (konto_id);

-- Fehlgeschlagene Code-Eingaben (Schutz gegen Durchprobieren)
create table fehlversuch (
  id    bigint generated always as identity primary key,
  zeit  timestamptz not null default now(),
  art   text not null
);
create index fehlversuch_zeit on fehlversuch (zeit);

-- ---------------------------------------------------------------------
--  3. standort_id an allen Daten, die zu einem Standort gehören
-- ---------------------------------------------------------------------
do $$
declare
  t  text;
  v  bigint := (select id from standort where name = 'RSZ Schwerin');
begin
  foreach t in array array['sportler', 'kategorie', 'tag', 'artikel', 'rad', 'stueck', 'ticket', 'rechnung', 'buchung', 'koffer_soll', 'termin', 'zaehlung', 'inventur_lauf', 'bestellung'] loop
    execute format('alter table %I add column standort_id bigint references standort (id)', t);
    execute format('update %I set standort_id = %s', t, v);
    execute format('alter table %I alter column standort_id set not null', t);
  end loop;
end $$;
create index artikel_standort on artikel (standort_id);
create index stueck_standort on stueck (standort_id);
create index ticket_standort on ticket (standort_id);
create index buchung_standort on buchung (standort_id);

-- Eindeutig je Standort statt überall
do $$
declare
  c record;
begin
  -- alte Eindeutigkeit von sportler(name), kategorie(name), tag(buchstabe, name), rechnung(nummer)
  for c in
    select con.conname, cl.relname
      from pg_constraint con join pg_class cl on cl.oid = con.conrelid
     where con.contype = 'u' and cl.relnamespace = 'public'::regnamespace
       and (cl.relname, (select array_agg(a.attname::text order by a.attname)
                           from pg_attribute a where a.attrelid = con.conrelid and a.attnum = any (con.conkey)))
           in (('sportler', array['name']), ('kategorie', array['name']), ('tag', array['buchstabe', 'name']), ('rechnung', array['nummer']))
  loop
    execute format('alter table %I drop constraint %I', c.relname, c.conname);
  end loop;
end $$;
alter table kategorie drop constraint kategorie_pkey;
alter table kategorie add constraint kategorie_pkey primary key (standort_id, buchstabe);
alter table sportler  add constraint sportler_name_key unique (standort_id, name);
alter table kategorie add constraint kategorie_name_key unique (standort_id, name);
alter table tag       add constraint tag_buchstabe_name_key unique (standort_id, buchstabe, name);
alter table rechnung  add constraint rechnung_nummer_key unique (standort_id, nummer);

-- Codes bekommen das Kürzel des Standorts: B-101 → SN-B-101, BR-01 → SN-BR-01.
-- Verweise auf Artikel, Einzelstücke und Räder ziehen beim Umbenennen mit.
do $$
declare
  c record;
begin
  for c in
    select con.conname, cl.relname, pg_get_constraintdef(con.oid) as def
      from pg_constraint con join pg_class cl on cl.oid = con.conrelid
     where con.contype = 'f' and con.confupdtype <> 'c'
       and con.confrelid in ('artikel'::regclass, 'stueck'::regclass, 'rad'::regclass)
  loop
    execute format('alter table %I drop constraint %I', c.relname, c.conname);
    execute format('alter table %I add constraint %I %s on update cascade', c.relname, c.conname, c.def);
  end loop;
end $$;
alter table artikel drop constraint artikel_code_check;
update artikel set code = 'SN-' || code;
alter table artikel add constraint artikel_code_check check (code ~ '^[A-Z]{2,3}-[A-Z]+-[0-9]+$');
update stueck set nummer = 'SN-' || nummer;
update rad set id = 'SN-' || id;
-- Pauschalen aus der Zeit vor 5.0.0 werden über diesen Text als Paar erkannt
update buchung set notiz = 'Verbrauch aus SN-' || substr(notiz, 15) where notiz like 'Verbrauch aus %';

-- ---------------------------------------------------------------------
--  4. Funktionen
-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
--  Wer fragt? — Sitzung und Standort kommen als Kopfzeilen mit jeder
--  Anfrage (X-Sitzung, X-Standort). Alle Prüfungen stützen sich darauf.
-- ---------------------------------------------------------------------
create or replace function kopfzeile(p_name text) returns text
language sql stable set search_path = public, pg_temp as $$
  select nullif(nullif(current_setting('request.headers', true), '')::json ->> p_name, '');
$$;

create or replace function token_hash(p_token text) returns text
language sql immutable as $$
  select encode(sha256(convert_to(p_token, 'UTF8')), 'hex');
$$;

-- Konto der laufenden Anfrage (gültige Sitzung, aktives Konto) oder null.
create or replace function ich_id() returns bigint
language sql stable security definer set search_path = public, pg_temp as $$
  select s.konto_id
    from sitzung s join konto k on k.id = s.konto_id
   where s.token_hash = token_hash(kopfzeile('x-sitzung'))
     and s.gueltig_bis > now() and k.aktiv;
$$;

create or replace function ich_name() returns text
language sql stable security definer set search_path = public, pg_temp as $$
  select name from konto where id = ich_id();
$$;

create or replace function ist_admin() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((select gesamt_admin from konto where id = ich_id()), false);
$$;

-- Der Standort aus X-Standort — nur, wenn das Konto dort eine Rolle hat
-- (der Gesamt-Admin darf überall hin).
create or replace function akt_standort() returns bigint
language sql stable security definer set search_path = public, pg_temp as $$
  select st.id
    from standort st
   where st.aktiv
     and st.id = (select case when kopfzeile('x-standort') ~ '^[0-9]{1,18}$' then kopfzeile('x-standort')::bigint end)
     and (ist_admin() or exists (select 1 from konto_rolle r where r.konto_id = ich_id() and r.standort_id = st.id));
$$;

-- admin | manager | trainer | geschaeftsstelle | sportler | null
create or replace function meine_rolle() returns text
language sql stable security definer set search_path = public, pg_temp as $$
  select case
           when akt_standort() is null then null
           when ist_admin() then 'admin'
           else (select r.rolle from konto_rolle r where r.konto_id = ich_id() and r.standort_id = akt_standort())
         end;
$$;

create or replace function rolle_in(variadic p_rollen text[]) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(meine_rolle() = any (p_rollen), false);
$$;

-- Der Sportler hinter einem Sportler-Konto (sonst null).
create or replace function mein_sportler() returns bigint
language sql stable security definer set search_path = public, pg_temp as $$
  select k.sportler_id from konto k where k.id = ich_id() and meine_rolle() = 'sportler';
$$;

-- „Sein“ Rad: er fährt es gerade oder es gehört ihm.
create or replace function mein_rad(p_rad text) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from rad r
     where r.id = p_rad and r.standort_id = akt_standort()
       and (r.eigentuemer_id = mein_sportler()
            or exists (select 1 from zuordnung z
                        where z.rad_id = r.id and z.gueltig_bis is null and z.sportler_id = mein_sportler())));
$$;

-- Rechte in Funktionen: gibt den Standort zurück oder bricht ab.
create or replace function recht(variadic p_rollen text[]) returns bigint
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v bigint;
begin
  if ich_id() is null then
    raise exception 'Nicht angemeldet – bitte neu anmelden' using errcode = '28000';
  end if;
  v := akt_standort();
  if v is null then raise exception 'Kein Zugriff auf diesen Standort'; end if;
  if not rolle_in(variadic p_rollen) then raise exception 'Keine Berechtigung'; end if;
  return v;
end $$;

create or replace function recht_arbeiten() returns bigint
language sql stable security definer set search_path = public, pg_temp as $$
  select recht('admin', 'manager', 'trainer');
$$;
create or replace function recht_rechnen() returns bigint
language sql stable security definer set search_path = public, pg_temp as $$
  select recht('admin', 'manager', 'geschaeftsstelle');
$$;
create or replace function recht_manager() returns bigint
language sql stable security definer set search_path = public, pg_temp as $$
  select recht('admin', 'manager');
$$;

-- ---------------------------------------------------------------------
--  Codes, PINs, Sitzungen
-- ---------------------------------------------------------------------
-- 8 Zeichen ohne Verwechsler (kein 0/O, 1/I/L), als XXXX-XXXX.
create or replace function neuer_code() returns text
language plpgsql volatile set search_path = public, extensions, pg_temp as $$
declare
  z  text  := '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
  b  bytea := gen_random_bytes(8);
  c  text  := '';
begin
  for i in 0 .. 7 loop
    c := c || substr(z, (get_byte(b, i) % 31) + 1, 1);
    if i = 3 then c := c || '-'; end if;
  end loop;
  return c;
end $$;

create or replace function code_hash(p_code text) returns text
language sql immutable as $$
  select token_hash(regexp_replace(upper(coalesce(p_code, '')), '[^A-Z0-9]', '', 'g'));
$$;

-- Manager, Geschäftsstelle und Gesamt-Admin: 6 Ziffern, sonst 4.
create or replace function pin_laenge(p_konto bigint) returns integer
language sql stable security definer set search_path = public, pg_temp as $$
  select case when exists (select 1 from konto where id = p_konto and gesamt_admin)
                or exists (select 1 from konto_rolle where konto_id = p_konto and rolle in ('manager', 'geschaeftsstelle'))
              then 6 else 4 end;
$$;

-- Fehlertext oder null
create or replace function pin_fehler(p_konto bigint, p_pin text) returns text
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  n integer := pin_laenge(p_konto);
begin
  if coalesce(p_pin, '') !~ '^[0-9]+$' then return 'Die PIN besteht nur aus Ziffern.'; end if;
  if length(p_pin) < n then return 'Die PIN braucht mindestens ' || n || ' Ziffern.'; end if;
  if length(p_pin) > 12 then return 'Höchstens 12 Ziffern.'; end if;
  if p_pin ~ '^(.)\1*$' then return 'Bitte nicht nur eine Ziffer wiederholen.'; end if;
  if strpos('01234567890123456789', p_pin) > 0 or strpos('98765432109876543210', p_pin) > 0 then
    return 'Bitte keine einfache Zahlenfolge.';
  end if;
  return null;
end $$;

-- Gegen Durchprobieren von Einladungscodes: höchstens 30 Fehlversuche
-- in 10 Minuten — für alle zusammen.
create or replace function zu_viele_versuche() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select count(*) >= 30 from fehlversuch where art = 'code' and zeit > now() - interval '10 minutes';
$$;
create or replace function fehlversuch_merken(p_art text) returns void
language sql volatile security definer set search_path = public, pg_temp as $$
  delete from fehlversuch where zeit < now() - interval '1 day';
  insert into fehlversuch (art) values (p_art);
$$;

create or replace function einladung_erzeugen(p_konto bigint) returns jsonb
language plpgsql volatile security definer set search_path = public, extensions, pg_temp as $$
declare
  v_code  text;
  v_bis   timestamptz := now() + interval '7 days';
begin
  delete from einladung where konto_id = p_konto;
  loop
    v_code := neuer_code();
    begin
      insert into einladung (code_hash, konto_id, gueltig_bis, angelegt_von)
      values (code_hash(v_code), p_konto, v_bis, ich_name());
      exit;
    exception when unique_violation then
      -- derselbe Code ist schon vergeben (äußerst selten): neuer Versuch
    end;
  end loop;
  return jsonb_build_object('code', v_code, 'gueltig_bis', v_bis);
end $$;

create or replace function sitzung_erzeugen(p_konto bigint, p_geraet text, p_bleiben boolean) returns jsonb
language plpgsql volatile security definer set search_path = public, extensions, pg_temp as $$
declare
  t      text := encode(gen_random_bytes(32), 'hex');
  v_bis  timestamptz;
  v_g    text := case when p_geraet = 'werkstatt' then 'werkstatt' else 'handy' end;
begin
  delete from sitzung where gueltig_bis < now();
  if v_g = 'werkstatt' then
    -- Werkstatt-Laptop: alle werden um 23 Uhr ausgetragen
    v_bis := ((now() at time zone 'Europe/Berlin')::date + time '23:00') at time zone 'Europe/Berlin';
    if v_bis <= now() + interval '10 minutes' then v_bis := v_bis + interval '1 day'; end if;
  elsif coalesce(p_bleiben, true) then
    v_bis := now() + interval '90 days';
  else
    v_bis := now() + interval '12 hours';
  end if;
  insert into sitzung (token_hash, konto_id, gueltig_bis, geraet) values (token_hash(t), p_konto, v_bis, v_g);
  update konto set zuletzt = now(), fehlversuche = 0, gesperrt_bis = null where id = p_konto;
  return jsonb_build_object('token', t, 'gueltig_bis', v_bis);
end $$;

-- Was die App über ein Konto wissen muss
create or replace function konto_info(p_konto bigint) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
           'konto_id', k.id, 'name', k.name, 'gesamt_admin', k.gesamt_admin, 'sportler_id', k.sportler_id,
           'pin_laenge', pin_laenge(k.id),
           'standorte', coalesce((
             select jsonb_agg(jsonb_build_object('id', st.id, 'name', st.name, 'kuerzel', st.kuerzel,
                                                 'rolle', coalesce(r.rolle, 'admin')) order by st.name)
               from standort st
               left join konto_rolle r on r.standort_id = st.id and r.konto_id = k.id
              where st.aktiv and (k.gesamt_admin or r.konto_id is not null)), '[]'::jsonb))
    from konto k where k.id = p_konto;
$$;

-- ---------------------------------------------------------------------
--  Anmelden (ohne Sitzung aufrufbar)
-- ---------------------------------------------------------------------
create or replace function standorte_liste() returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'kuerzel', kuerzel) order by name), '[]'::jsonb)
    from standort where aktiv;
$$;

-- Kacheln am Anmeldebildschirm: Manager, Trainer, Geschäftsstelle mit PIN.
-- Sportler stehen nicht in der Liste, sie tippen ihren Namen ein.
create or replace function anmelde_liste(p_standort bigint) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'name', k.name, 'rolle', r.rolle)
                            order by array_position(array['manager', 'trainer', 'geschaeftsstelle'], r.rolle), lower(k.name)), '[]'::jsonb)
    from konto k join konto_rolle r on r.konto_id = k.id and r.standort_id = p_standort
   where k.aktiv and k.pin_hash is not null and r.rolle in ('manager', 'trainer', 'geschaeftsstelle');
$$;

-- Fehler kommen als {ok:false, fehler:…} zurück (nicht als Abbruch),
-- damit gezählte Fehlversuche gespeichert bleiben.
create or replace function anmelden(p_standort bigint, p_pin text, p_konto bigint default null, p_name text default null,
                                    p_geraet text default 'handy', p_bleiben boolean default true)
returns jsonb
language plpgsql volatile security definer set search_path = public, extensions, pg_temp as $$
declare
  k       konto;
  n       integer;
  v_s     jsonb;
begin
  if p_konto is not null then
    select * into k from konto where id = p_konto and aktiv;
  else
    select count(*) into n
      from konto x
     where x.aktiv and lower(trim(x.name)) = lower(trim(coalesce(p_name, '')))
       and (x.gesamt_admin or exists (select 1 from konto_rolle r where r.konto_id = x.id and r.standort_id = p_standort));
    if n > 1 then
      return jsonb_build_object('ok', false, 'fehler', 'Den Namen gibt es mehrfach – bitte den Werkstatt-Manager fragen.');
    end if;
    select * into k
      from konto x
     where x.aktiv and lower(trim(x.name)) = lower(trim(coalesce(p_name, '')))
       and (x.gesamt_admin or exists (select 1 from konto_rolle r where r.konto_id = x.id and r.standort_id = p_standort));
  end if;

  if k.id is null
     or not (k.gesamt_admin or exists (select 1 from konto_rolle r where r.konto_id = k.id and r.standort_id = p_standort)) then
    return jsonb_build_object('ok', false, 'fehler', 'Name oder PIN falsch.');
  end if;
  if k.gesperrt_bis is not null and k.gesperrt_bis > now() then
    return jsonb_build_object('ok', false, 'fehler',
      'Zu viele Fehlversuche – wieder möglich ab ' || to_char(k.gesperrt_bis at time zone 'Europe/Berlin', 'HH24:MI') || ' Uhr.');
  end if;
  if k.pin_hash is null then
    return jsonb_build_object('ok', false, 'fehler', 'Noch keine PIN gesetzt – bitte mit dem Einladungscode anmelden.');
  end if;
  if crypt(coalesce(p_pin, ''), k.pin_hash) <> k.pin_hash then
    update konto set fehlversuche = fehlversuche + 1 where id = k.id returning fehlversuche into n;
    if n >= 5 then
      update konto set fehlversuche = 0, gesperrt_bis = now() + interval '15 minutes' where id = k.id;
      return jsonb_build_object('ok', false, 'fehler', 'PIN falsch – das Konto ist jetzt 15 Minuten gesperrt.');
    end if;
    return jsonb_build_object('ok', false, 'fehler', 'Name oder PIN falsch (noch ' || (5 - n) || ' Versuche).');
  end if;

  v_s := sitzung_erzeugen(k.id, p_geraet, p_bleiben);
  return jsonb_build_object('ok', true) || v_s || jsonb_build_object('konto', konto_info(k.id));
end $$;

-- Vor dem PIN-Setzen: zu wem gehört der Code?
create or replace function einladung_pruefen(p_code text) returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_k  bigint;
begin
  if zu_viele_versuche() then
    return jsonb_build_object('ok', false, 'fehler', 'Zu viele Versuche – bitte in ein paar Minuten noch einmal.');
  end if;
  select konto_id into v_k from einladung where code_hash = code_hash(p_code) and gueltig_bis > now();
  if v_k is null then
    perform fehlversuch_merken('code');
    return jsonb_build_object('ok', false, 'fehler', 'Code ungültig oder abgelaufen.');
  end if;
  return jsonb_build_object('ok', true, 'name', (select name from konto where id = v_k), 'pin_laenge', pin_laenge(v_k));
end $$;

create or replace function einladung_einloesen(p_code text, p_pin text, p_geraet text default 'handy', p_bleiben boolean default true)
returns jsonb
language plpgsql volatile security definer set search_path = public, extensions, pg_temp as $$
declare
  v_k  bigint;
  v_f  text;
  v_s  jsonb;
begin
  if zu_viele_versuche() then
    return jsonb_build_object('ok', false, 'fehler', 'Zu viele Versuche – bitte in ein paar Minuten noch einmal.');
  end if;
  select e.konto_id into v_k
    from einladung e join konto k on k.id = e.konto_id
   where e.code_hash = code_hash(p_code) and e.gueltig_bis > now() and k.aktiv;
  if v_k is null then
    perform fehlversuch_merken('code');
    return jsonb_build_object('ok', false, 'fehler', 'Code ungültig oder abgelaufen.');
  end if;
  v_f := pin_fehler(v_k, p_pin);
  if v_f is not null then return jsonb_build_object('ok', false, 'fehler', v_f); end if;

  update konto set pin_hash = crypt(p_pin, gen_salt('bf', 8)), fehlversuche = 0, gesperrt_bis = null where id = v_k;
  delete from einladung where konto_id = v_k;
  delete from sitzung where konto_id = v_k;
  v_s := sitzung_erzeugen(v_k, p_geraet, p_bleiben);
  return jsonb_build_object('ok', true) || v_s || jsonb_build_object('konto', konto_info(v_k));
end $$;

-- Mit Sitzung: wer bin ich, wo bin ich?
create or replace function ich() returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select case when ich_id() is null then null
              else konto_info(ich_id()) || jsonb_build_object('rolle', meine_rolle(), 'standort_id', akt_standort()) end;
$$;

create or replace function abmelden() returns void
language sql volatile security definer set search_path = public, pg_temp as $$
  delete from sitzung where token_hash = token_hash(kopfzeile('x-sitzung'));
$$;

create or replace function pin_aendern(p_alt text, p_neu text) returns void
language plpgsql volatile security definer set search_path = public, extensions, pg_temp as $$
declare
  k    konto;
  v_f  text;
begin
  select * into k from konto where id = ich_id();
  if k.id is null then raise exception 'Nicht angemeldet – bitte neu anmelden' using errcode = '28000'; end if;
  if k.pin_hash is null or crypt(coalesce(p_alt, ''), k.pin_hash) <> k.pin_hash then
    raise exception 'Bisherige PIN stimmt nicht';
  end if;
  v_f := pin_fehler(k.id, p_neu);
  if v_f is not null then raise exception '%', v_f; end if;
  update konto set pin_hash = crypt(p_neu, gen_salt('bf', 8)) where id = k.id;
  -- andere Geräte abmelden, dieses bleibt
  delete from sitzung where konto_id = k.id and token_hash <> token_hash(kopfzeile('x-sitzung'));
end $$;

-- ---------------------------------------------------------------------
--  Konten verwalten (Werkstatt-Manager, Gesamt-Admin)
-- ---------------------------------------------------------------------
create or replace function konten_liste() returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_st  bigint := recht_manager();
begin
  return coalesce((
    select jsonb_agg(z order by array_position(array['admin', 'manager', 'trainer', 'geschaeftsstelle', 'sportler'], z ->> 'rolle'),
                                lower(z ->> 'name'))
      from (
        select jsonb_build_object('id', k.id, 'name', k.name, 'rolle', r.rolle, 'aktiv', k.aktiv,
                                  'pin_gesetzt', k.pin_hash is not null, 'einladung_bis', e.gueltig_bis,
                                  'zuletzt', k.zuletzt, 'sportler_id', k.sportler_id,
                                  'gesperrt', coalesce(k.gesperrt_bis > now(), false)) as z
          from konto k
          join konto_rolle r on r.konto_id = k.id and r.standort_id = v_st
          left join einladung e on e.konto_id = k.id
         where not k.gesamt_admin
        union all
        select jsonb_build_object('id', k.id, 'name', k.name, 'rolle', 'admin', 'aktiv', k.aktiv,
                                  'pin_gesetzt', k.pin_hash is not null, 'einladung_bis', e.gueltig_bis,
                                  'zuletzt', k.zuletzt, 'sportler_id', null, 'gesperrt', coalesce(k.gesperrt_bis > now(), false))
          from konto k
          left join einladung e on e.konto_id = k.id
         where k.gesamt_admin
      ) x), '[]'::jsonb);
end $$;

-- Gibt es den Namen an diesem Standort schon (außer bei p_ausser)?
create or replace function name_vergeben(p_standort bigint, p_name text, p_ausser bigint default null) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from konto k
                  where lower(trim(k.name)) = lower(trim(p_name)) and k.id is distinct from p_ausser
                    and (k.gesamt_admin or exists (select 1 from konto_rolle r where r.konto_id = k.id and r.standort_id = p_standort)));
$$;

create or replace function konto_anlegen(p_name text, p_rolle text, p_sportler bigint default null) returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_st    bigint := recht_manager();
  v_name  text   := trim(coalesce(p_name, ''));
  v_id    bigint;
begin
  if p_rolle not in ('manager', 'trainer', 'geschaeftsstelle', 'sportler') then raise exception 'Unbekannte Rolle: %', p_rolle; end if;
  if p_rolle = 'manager' and not ist_admin() then
    raise exception 'Werkstatt-Manager lädt nur der Gesamt-Admin ein';
  end if;
  if p_rolle = 'sportler' then
    if p_sportler is null then raise exception 'Sportler fehlt'; end if;
    if v_name = '' then select name into v_name from sportler where id = p_sportler and standort_id = v_st; end if;
    if not exists (select 1 from sportler where id = p_sportler and standort_id = v_st) then raise exception 'Unbekannter Sportler'; end if;
    if exists (select 1 from konto where sportler_id = p_sportler) then
      raise exception 'Hat schon einen Zugang – dort „neuer Code“ wählen';
    end if;
  else
    p_sportler := null;
  end if;
  if v_name = '' then raise exception 'Name fehlt'; end if;
  if name_vergeben(v_st, v_name) then raise exception 'Den Namen gibt es an diesem Standort schon'; end if;

  insert into konto (name, sportler_id) values (v_name, p_sportler) returning id into v_id;
  insert into konto_rolle (konto_id, standort_id, rolle) values (v_id, v_st, p_rolle);
  return jsonb_build_object('konto_id', v_id, 'name', v_name) || einladung_erzeugen(v_id);
end $$;

-- Prüft, ob der Aufrufer das Konto verwalten darf; gibt dessen Rolle hier zurück.
create or replace function konto_verwaltbar(p_konto bigint) returns text
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_st  bigint := recht_manager();
  k     konto;
  v_r   text;
begin
  select * into k from konto where id = p_konto;
  if k.id is null then raise exception 'Unbekanntes Konto'; end if;
  if k.gesamt_admin then raise exception 'Den Gesamt-Admin nur über den Neon SQL-Editor (notfall_code)'; end if;
  select rolle into v_r from konto_rolle where konto_id = p_konto and standort_id = v_st;
  if v_r is null then raise exception 'Das Konto gehört nicht zu diesem Standort'; end if;
  if v_r = 'manager' and not ist_admin() then raise exception 'Einen Werkstatt-Manager verwaltet nur der Gesamt-Admin'; end if;
  return v_r;
end $$;

-- PIN vergessen / neu einladen: alte PIN gilt nicht mehr, alle Geräte abgemeldet.
create or replace function konto_neuer_code(p_konto bigint) returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
begin
  perform konto_verwaltbar(p_konto);
  update konto set pin_hash = null, fehlversuche = 0, gesperrt_bis = null where id = p_konto;
  delete from sitzung where konto_id = p_konto;
  return jsonb_build_object('konto_id', p_konto, 'name', (select name from konto where id = p_konto)) || einladung_erzeugen(p_konto);
end $$;

create or replace function konto_aendern(p_konto bigint, p_name text default null, p_rolle text default null, p_aktiv boolean default null)
returns void
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_st  bigint := recht_manager();
  v_r   text   := konto_verwaltbar(p_konto);
begin
  if p_name is not null then
    if trim(p_name) = '' then raise exception 'Name fehlt'; end if;
    if name_vergeben(v_st, p_name, p_konto) then raise exception 'Den Namen gibt es an diesem Standort schon'; end if;
    update konto set name = trim(p_name) where id = p_konto;
  end if;
  if p_rolle is not null and p_rolle <> v_r then
    if p_rolle not in ('manager', 'trainer', 'geschaeftsstelle') or v_r = 'sportler' then
      raise exception 'Diese Rolle lässt sich nicht ändern';
    end if;
    if p_rolle = 'manager' and not ist_admin() then raise exception 'Werkstatt-Manager ernennt nur der Gesamt-Admin'; end if;
    update konto_rolle set rolle = p_rolle where konto_id = p_konto and standort_id = v_st;
  end if;
  if p_aktiv is not null then
    update konto set aktiv = p_aktiv where id = p_konto;
    if not p_aktiv then delete from sitzung where konto_id = p_konto; end if;
  end if;
end $$;

-- „Zugang einladen“ auf der Sportler-Seite: neues Konto oder neuer Code.
create or replace function sportler_zugang(p_sportler bigint) returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_st  bigint := recht_manager();
  v_k   bigint;
begin
  if not exists (select 1 from sportler where id = p_sportler and standort_id = v_st) then raise exception 'Unbekannter Sportler'; end if;
  select id into v_k from konto where sportler_id = p_sportler;
  if v_k is null then return konto_anlegen(null, 'sportler', p_sportler); end if;
  update konto set aktiv = true where id = v_k;
  return konto_neuer_code(v_k);
end $$;

-- ---------------------------------------------------------------------
--  Standorte (Gesamt-Admin)
-- ---------------------------------------------------------------------
create or replace function standard_kategorien(p_standort bigint) returns void
language sql volatile security definer set search_path = public, pg_temp as $$
  insert into kategorie (standort_id, buchstabe, name) values
    (p_standort, 'A', 'Antrieb'),
    (p_standort, 'B', 'Bremse'),
    (p_standort, 'C', 'Cockpit & Vorbau'),
    (p_standort, 'L', 'Laufrad & Reifen'),
    (p_standort, 'R', 'Rahmen'),
    (p_standort, 'W', 'Werkstattmaterial')
  on conflict do nothing;
$$;

create or replace function standort_anlegen(p_name text, p_kuerzel text) returns bigint
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_id bigint;
begin
  if ich_id() is null then raise exception 'Nicht angemeldet – bitte neu anmelden' using errcode = '28000'; end if;
  if not ist_admin() then raise exception 'Standorte legt nur der Gesamt-Admin an'; end if;
  if trim(coalesce(p_name, '')) = '' then raise exception 'Name fehlt'; end if;
  if upper(trim(coalesce(p_kuerzel, ''))) !~ '^[A-Z]{2,3}$' then raise exception 'Kürzel: 2 bis 3 Buchstaben A–Z'; end if;
  if exists (select 1 from standort where kuerzel = upper(trim(p_kuerzel))) then raise exception 'Das Kürzel ist schon vergeben'; end if;
  insert into standort (name, kuerzel) values (trim(p_name), upper(trim(p_kuerzel))) returning id into v_id;
  perform standard_kategorien(v_id);
  return v_id;
end $$;

-- Nur im Neon SQL-Editor (keine Freigabe für die App): neuer Einladungscode
-- für ein Konto, z. B. wenn der Gesamt-Admin seine PIN vergessen hat.
-- Aufruf: select notfall_code('Hauke');
create or replace function notfall_code(p_name text) returns text
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_k   bigint;
  n     integer;
  v_e   jsonb;
begin
  select count(*) into n from konto where lower(trim(name)) = lower(trim(p_name));
  if n = 0 then raise exception 'Kein Konto mit dem Namen %', p_name; end if;
  if n > 1 then raise exception 'Den Namen % gibt es mehrfach', p_name; end if;
  select id into v_k from konto where lower(trim(name)) = lower(trim(p_name));
  update konto set pin_hash = null, fehlversuche = 0, gesperrt_bis = null, aktiv = true where id = v_k;
  delete from sitzung where konto_id = v_k;
  v_e := einladung_erzeugen(v_k);
  return 'Code ' || (v_e ->> 'code') || ' für ' || p_name || ' – gültig bis '
         || to_char((v_e ->> 'gueltig_bis')::timestamptz at time zone 'Europe/Berlin', 'DD.MM.YYYY HH24:MI')
         || '. In der App „Code“ wählen und eine PIN setzen.';
end $$;

-- ---------------------------------------------------------------------
--  Wer hat es gemacht? — immer das angemeldete Konto, nicht ein Name,
--  den die App mitschickt.
-- ---------------------------------------------------------------------
create or replace function bearbeiter_setzen() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  new.bearbeiter := coalesce(ich_name(), new.bearbeiter);
  return new;
end $$;

create or replace function ticket_uebernahme() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.uebernommen_von is distinct from old.uebernommen_von and new.uebernommen_von is not null then
    new.uebernommen_von := coalesce(ich_name(), new.uebernommen_von);
  end if;
  return new;
end $$;

-- Preise ändern nur Werkstatt-Manager (und Gesamt-Admin).
create or replace function preis_schutz() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.preis is distinct from old.preis and ich_id() is not null and not rolle_in('admin', 'manager') then
    raise exception 'Preise ändert nur der Werkstatt-Manager';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------
--  Funktionen für alles, was in einem Schritt passieren muss.
--  Jede prüft zuerst Anmeldung, Rolle und Standort (recht_…) und sieht
--  nur Daten dieses Standorts. Wer bucht, steht im Konto — der mit-
--  geschickte Name (p_bearbeiter) wird ersetzt.
-- ---------------------------------------------------------------------

-- Material ausgeben — mit oder ohne Ticket. Preis wird festgeschrieben;
-- Pauschalen ziehen zusätzlich ihren hinterlegten Verbrauch ab.
create or replace function material_ausgeben(
  p_code text, p_menge numeric, p_ort text default 'Werkstatt',
  p_sportler bigint default null, p_ticket bigint default null, p_notiz text default null,
  p_bearbeiter text default null
) returns numeric
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st   bigint := recht_arbeiten();
  a      artikel;
  v_abr  boolean := false;
  v_grp  uuid;
begin
  p_bearbeiter := ich_name();
  if p_menge is null or p_menge <= 0 then raise exception 'Menge muss größer als 0 sein'; end if;
  select * into a from artikel where code = p_code and standort_id = v_st;
  if not found then raise exception 'Unbekannter Artikel: %', p_code; end if;
  if p_sportler is not null then
    select abrechnen into v_abr from sportler where id = p_sportler and standort_id = v_st;
    if not found then raise exception 'Unbekannter Sportler'; end if;
  end if;
  if p_ticket is not null and not exists (select 1 from ticket where id = p_ticket and standort_id = v_st) then
    raise exception 'Ticket % nicht gefunden', p_ticket;
  end if;
  if a.art = 'Pauschale' and a.verbraucht_code is not null and a.verbrauch_menge is not null then
    v_grp := gen_random_uuid();
  end if;

  insert into buchung (art, code, menge, ort, sportler_id, ticket_id, einzelpreis, abrechnen, notiz, bearbeiter, gruppe, standort_id)
  values ('entnahme', p_code, -p_menge, p_ort, p_sportler, p_ticket, a.preis, coalesce(v_abr, false), p_notiz, p_bearbeiter, v_grp, v_st);

  if v_grp is not null then
    insert into buchung (art, code, menge, ort, sportler_id, ticket_id, einzelpreis, abrechnen, notiz, bearbeiter, gruppe, standort_id)
    values ('entnahme', a.verbraucht_code, -(a.verbrauch_menge * p_menge), p_ort,
            p_sportler, p_ticket, 0, false, 'Verbrauch aus ' || p_code, p_bearbeiter, v_grp, v_st);
  end if;

  return a.preis * p_menge;
end $$;

-- Material zwischen Werkstatt und Koffern verschieben (zwei Buchungen).
create or replace function umbuchen(p_code text, p_menge numeric, p_von text, p_nach text,
                                    p_notiz text default null, p_bearbeiter text default null)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st bigint := recht_arbeiten();
  g    uuid   := gen_random_uuid();
begin
  p_bearbeiter := ich_name();
  if p_von = p_nach then raise exception 'Von und nach sind gleich'; end if;
  if p_menge is null or p_menge <= 0 then raise exception 'Menge muss größer als 0 sein'; end if;
  if not exists (select 1 from artikel where code = p_code and standort_id = v_st) then raise exception 'Unbekannter Artikel: %', p_code; end if;
  insert into buchung (art, code, menge, ort, gruppe, notiz, bearbeiter, standort_id) values
    ('umbuchung', p_code, -p_menge, p_von,  g, p_notiz, p_bearbeiter, v_st),
    ('umbuchung', p_code,  p_menge, p_nach, g, p_notiz, p_bearbeiter, v_st);
end $$;

-- Inventur: gezählten Bestand eintragen, die Differenz wird gebucht.
create or replace function inventur(p_code text, p_ort text, p_gezaehlt numeric, p_bearbeiter text default null)
returns numeric
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st    bigint := recht_arbeiten();
  v_ist   numeric;
  v_diff  numeric;
begin
  p_bearbeiter := ich_name();
  if p_gezaehlt is null or p_gezaehlt < 0 then raise exception 'Gezählte Menge fehlt'; end if;
  if not exists (select 1 from artikel where code = p_code and standort_id = v_st) then raise exception 'Unbekannter Artikel: %', p_code; end if;
  select coalesce(sum(menge), 0) into v_ist from buchung where code = p_code and ort = p_ort and standort_id = v_st;
  v_diff := p_gezaehlt - v_ist;
  if v_diff <> 0 then
    insert into buchung (art, code, menge, ort, notiz, bearbeiter, standort_id)
    values ('korrektur', p_code, v_diff, p_ort, 'Inventur: gezählt ' || p_gezaehlt || ', vorher ' || v_ist, p_bearbeiter, v_st);
  end if;
  insert into zaehlung (code, ort, bearbeiter, standort_id) values (p_code, p_ort, p_bearbeiter, v_st)
  on conflict (code, ort) do update set gezaehlt_am = now(), bearbeiter = excluded.bearbeiter;
  return v_diff;
end $$;

-- Ticket anlegen samt vorgemerktem Material, in einem Schritt. Kommt dieselbe
-- Kennung vom Gerät ein zweites Mal (Nachsenden nach Funkloch), gibt es kein
-- zweites Ticket. Einzelstücke: p_stuecke (Liste) und/oder p_stueck (eines).
-- Sportler dürfen Tickets für ihre eigenen Räder anlegen — ohne Material und
-- Arbeitsschritte, nur in der Werkstatt.
create or replace function ticket_anlegen(
  p_rad text, p_problem text, p_fahrbereit boolean,
  p_soll_fertig date default null, p_naechstmoeglich boolean default false,
  p_anlass text default null, p_arbeitsort text default 'Werkstatt',
  p_positionen jsonb default '[]'::jsonb, p_bearbeiter text default null,
  p_client_id uuid default null, p_stueck text default null, p_stuecke text[] default null
) returns bigint
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st       bigint;
  v_rolle    text;
  v_id       bigint;
  v_rad      text := nullif(trim(coalesce(p_rad, '')), '');
  v_fahrer   bigint;
  v_kt       bigint;
  v_pos      jsonb;
  v_stuecke  text[];
  v_fehlt    text;
  v_raeder   text[];
begin
  if ich_id() is null then raise exception 'Nicht angemeldet – bitte neu anmelden' using errcode = '28000'; end if;
  v_st := akt_standort();
  if v_st is null then raise exception 'Kein Zugriff auf diesen Standort'; end if;
  v_rolle := meine_rolle();
  if v_rolle not in ('admin', 'manager', 'trainer', 'sportler') then raise exception 'Keine Berechtigung'; end if;
  p_bearbeiter := ich_name();

  if p_client_id is not null then
    select id into v_id from ticket where client_id = p_client_id;
    if found then return v_id; end if;
  end if;

  if coalesce(trim(p_problem), '') = '' then raise exception 'Problem fehlt'; end if;

  -- Einzelstücke: beide Angaben zusammen, ohne Leere und Doppelte, Reihenfolge bleibt
  select coalesce(array_agg(n order by i), '{}') into v_stuecke
    from (select n, min(i) as i
            from unnest(coalesce(p_stuecke, '{}') || array[p_stueck]) with ordinality as x(n, i)
           where nullif(trim(n), '') is not null
           group by n) y;

  select string_agg(n, ', ') into v_fehlt
    from unnest(v_stuecke) as n where not exists (select 1 from stueck where nummer = n and standort_id = v_st);
  if v_fehlt is not null then raise exception 'Unbekanntes Einzelstück: %', v_fehlt; end if;

  -- Ohne Rad: stecken die Teile an genau einem Rad, gilt das Ticket für dieses Rad
  if v_rad is null and cardinality(v_stuecke) > 0 then
    select array_agg(distinct rad_id) into v_raeder from stueck where nummer = any (v_stuecke) and rad_id is not null;
    if cardinality(v_raeder) = 1 then v_rad := v_raeder[1]; end if;
  end if;
  if v_rad is null and cardinality(v_stuecke) = 0 then raise exception 'Rad oder Einzelstück fehlt'; end if;

  if v_rolle = 'sportler' then
    if v_rad is null or not mein_rad(v_rad) then raise exception 'Tickets nur für die eigenen Räder'; end if;
    if exists (select 1 from stueck where nummer = any (v_stuecke) and rad_id is distinct from v_rad) then
      raise exception 'Nur Teile, die an deinem Rad sind';
    end if;
    p_positionen := '[]'::jsonb;
    p_arbeitsort := 'Werkstatt';
  end if;

  if v_rad is not null then
    select eigentuemer_id into v_kt from rad where id = v_rad and standort_id = v_st;
    if not found then raise exception 'Unbekanntes Rad: %', v_rad; end if;
    select sportler_id into v_fahrer from zuordnung where rad_id = v_rad and gueltig_bis is null;
  end if;

  insert into ticket (rad_id, fahrer_id, problem, fahrbereit, soll_fertig, naechstmoeglich,
                      anlass, kostentraeger_id, arbeitsort, angelegt_von, client_id, standort_id)
  values (v_rad, v_fahrer, trim(p_problem), coalesce(p_fahrbereit, true), p_soll_fertig, coalesce(p_naechstmoeglich, false),
          nullif(trim(p_anlass), ''), v_kt, p_arbeitsort, p_bearbeiter, p_client_id, v_st)
  on conflict (client_id) do nothing
  returning id into v_id;

  -- Gleichzeitig angekommen: das andere hat gewonnen, dessen Ticket gilt.
  if v_id is null then
    select id into v_id from ticket where client_id = p_client_id;
    return v_id;
  end if;

  insert into ticket_stueck (ticket_id, nummer) select v_id, n from unnest(v_stuecke) as n;

  -- Schritte: {"code":"A-104","menge":1} oder {"titel":"Laufrad zentrieren","dauer_min":20}
  for v_pos in select * from jsonb_array_elements(coalesce(p_positionen, '[]'::jsonb)) loop
    if nullif(v_pos ->> 'code', '') is not null
       and not exists (select 1 from artikel where code = v_pos ->> 'code' and standort_id = v_st) then
      raise exception 'Unbekannter Artikel: %', v_pos ->> 'code';
    end if;
    insert into ticket_position (ticket_id, code, titel, menge, dauer_min)
    values (v_id, nullif(v_pos ->> 'code', ''), nullif(trim(v_pos ->> 'titel'), ''),
            coalesce((v_pos ->> 'menge')::numeric, 1), (v_pos ->> 'dauer_min')::integer);
  end loop;

  -- Einzelstücke mit Ticket müssen geprüft werden: „frei“ wird zu „zu prüfen“
  -- („defekt“ bleibt „defekt“).
  update stueck set zustand = 'zu prüfen' where nummer = any (v_stuecke) and zustand = 'frei';

  return v_id;
end $$;

-- Ticket abschließen: alle noch offenen Schritte auf einmal (Material wird zur
-- Entnahme am Arbeitsort). Blockiert, solange ein Teil am Rad oder ein
-- Einzelstück des Tickets "zu prüfen" ist.
create or replace function ticket_abschliessen(p_ticket bigint, p_bearbeiter text default null) returns numeric
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st       bigint := recht_arbeiten();
  t          ticket;
  p          record;
  v_summe    numeric := 0;
  v_offen    text;
  v_buchung  bigint;
begin
  p_bearbeiter := ich_name();
  select * into t from ticket where id = p_ticket and standort_id = v_st for update;
  if not found then raise exception 'Ticket % nicht gefunden', p_ticket; end if;
  if t.status in ('erledigt', 'storniert') then raise exception 'Ticket ist bereits abgeschlossen'; end if;

  select string_agg(nummer, ', ' order by nummer) into v_offen
    from stueck
   where (rad_id = t.rad_id or nummer in (select nummer from ticket_stueck where ticket_id = p_ticket))
     and zustand = 'zu prüfen';
  if v_offen is not null then raise exception 'Erst prüfen und freigeben: %', v_offen; end if;

  for p in select * from ticket_position
            where ticket_id = p_ticket and status = 'reserviert' order by id for update loop
    if p.code is null then
      update ticket_position set status = 'erledigt', erledigt_am = now(), erledigt_von = p_bearbeiter where id = p.id;
    else
      v_summe := v_summe + material_ausgeben(p.code, p.menge, t.arbeitsort, t.kostentraeger_id, p_ticket, null, p_bearbeiter);
      select max(id) into v_buchung from buchung where ticket_id = p_ticket and code = p.code and art = 'entnahme';
      update ticket_position set status = 'gebucht', erledigt_am = now(), erledigt_von = p_bearbeiter, buchung_id = v_buchung
       where id = p.id;
    end if;
  end loop;

  update ticket set status = 'erledigt', erledigt_am = now(), erledigt_von = p_bearbeiter where id = p_ticket;
  return v_summe;
end $$;

-- Ticket stornieren: Ticket und alle Reservierungen in einem Schritt.
create or replace function ticket_stornieren(p_ticket bigint, p_bearbeiter text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st bigint := recht_arbeiten();
  t    ticket;
begin
  p_bearbeiter := ich_name();
  select * into t from ticket where id = p_ticket and standort_id = v_st for update;
  if not found then raise exception 'Ticket % nicht gefunden', p_ticket; end if;
  if t.status in ('erledigt', 'storniert') then raise exception 'Ticket ist bereits abgeschlossen'; end if;

  update ticket_position set status = 'storniert' where ticket_id = p_ticket and status = 'reserviert';
  update ticket set status = 'storniert', storniert_am = now(), storniert_von = p_bearbeiter where id = p_ticket;
end $$;

-- ---------------------------------------------------------------------
--  Einzelstücke eines offenen Tickets nachtragen (p_mit) oder
--  herausnehmen (p_ohne). Nachgetragene „freie“ Teile werden „zu prüfen“;
--  ein herausgenommenes Teil, das auf „zu prüfen“ steht und an keinem
--  anderen offenen Ticket hängt, wird wieder „frei“. Ein Ticket ohne Rad
--  behält mindestens ein Einzelstück.
-- ---------------------------------------------------------------------
create or replace function ticket_stuecke_aendern(p_ticket bigint, p_mit text[] default null, p_ohne text[] default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st     bigint := recht_arbeiten();
  t        ticket;
  v_fehlt  text;
  v_neu    text[];
  v_weg    text[];
begin
  select * into t from ticket where id = p_ticket and standort_id = v_st for update;
  if not found then raise exception 'Ticket % nicht gefunden', p_ticket; end if;
  if t.status not in ('offen', 'angenommen') then raise exception 'Ticket ist bereits abgeschlossen'; end if;

  select string_agg(n, ', ') into v_fehlt
    from unnest(coalesce(p_mit, '{}')) as n where not exists (select 1 from stueck where nummer = n and standort_id = v_st);
  if v_fehlt is not null then raise exception 'Unbekanntes Einzelstück: %', v_fehlt; end if;

  with neu as (
    insert into ticket_stueck (ticket_id, nummer)
      select p_ticket, n from unnest(coalesce(p_mit, '{}')) as n
       where not (n = any (coalesce(p_ohne, '{}')))
      on conflict do nothing
      returning nummer
  ) select coalesce(array_agg(nummer), '{}') into v_neu from neu;
  update stueck set zustand = 'zu prüfen' where nummer = any (v_neu) and zustand = 'frei';

  with weg as (
    delete from ticket_stueck where ticket_id = p_ticket and nummer = any (coalesce(p_ohne, '{}'))
      returning nummer
  ) select coalesce(array_agg(nummer), '{}') into v_weg from weg;
  update stueck s set zustand = 'frei'
   where s.nummer = any (v_weg) and s.zustand = 'zu prüfen'
     and not exists (select 1 from ticket_stueck ts join ticket x on x.id = ts.ticket_id
                      where ts.nummer = s.nummer and x.status in ('offen', 'angenommen'))
     and not exists (select 1 from ticket x where x.rad_id = s.rad_id and x.status in ('offen', 'angenommen'));

  if t.rad_id is null and not exists (select 1 from ticket_stueck where ticket_id = p_ticket) then
    raise exception 'Ein Ticket ohne Rad braucht mindestens ein Einzelstück';
  end if;
end $$;

-- ---------------------------------------------------------------------
--  Einen Schritt abhaken. Material wird sofort am Arbeitsort an den
--  Kostenträger gebucht; das Ticket bleibt offen. Gibt den Betrag zurück.
-- ---------------------------------------------------------------------
create or replace function position_erledigen(p_position bigint, p_bearbeiter text default null) returns numeric
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st       bigint := recht_arbeiten();
  v_tid      bigint;
  t          ticket;
  p          ticket_position;
  v_betrag   numeric := 0;
  v_buchung  bigint;
begin
  p_bearbeiter := ich_name();
  select ticket_id into v_tid from ticket_position where id = p_position;
  if not found then raise exception 'Schritt % nicht gefunden', p_position; end if;
  select * into t from ticket where id = v_tid and standort_id = v_st for update;          -- erst das Ticket, dann der Schritt (wie beim Abschließen)
  if not found then raise exception 'Schritt % nicht gefunden', p_position; end if;
  select * into p from ticket_position where id = p_position for update;
  if t.status not in ('offen', 'angenommen') then raise exception 'Ticket ist bereits abgeschlossen'; end if;
  if p.status <> 'reserviert' then raise exception 'Schritt ist schon erledigt oder freigegeben'; end if;

  if p.code is not null then
    v_betrag := material_ausgeben(p.code, p.menge, t.arbeitsort, t.kostentraeger_id, t.id, null, p_bearbeiter);
    select max(id) into v_buchung from buchung where ticket_id = t.id and code = p.code and art = 'entnahme';
    update ticket_position set status = 'gebucht', erledigt_am = now(), erledigt_von = p_bearbeiter, buchung_id = v_buchung
     where id = p.id;
  else
    update ticket_position set status = 'erledigt', erledigt_am = now(), erledigt_von = p_bearbeiter
     where id = p.id;
  end if;
  return v_betrag;
end $$;

-- ---------------------------------------------------------------------
--  Abgehakten Schritt zurücknehmen (vertippt). Die Buchung wird
--  storniert — nicht möglich, wenn sie schon auf einer Rechnung steht.
-- ---------------------------------------------------------------------
create or replace function position_zuruecknehmen(p_position bigint, p_bearbeiter text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st   bigint := recht_arbeiten();
  v_tid  bigint;
  t      ticket;
  p      ticket_position;
begin
  p_bearbeiter := ich_name();
  select ticket_id into v_tid from ticket_position where id = p_position;
  if not found then raise exception 'Schritt % nicht gefunden', p_position; end if;
  select * into t from ticket where id = v_tid and standort_id = v_st for update;
  if not found then raise exception 'Schritt % nicht gefunden', p_position; end if;
  select * into p from ticket_position where id = p_position for update;
  if t.status not in ('offen', 'angenommen') then raise exception 'Ticket ist bereits abgeschlossen'; end if;
  if p.status not in ('gebucht', 'erledigt') then raise exception 'Schritt ist nicht abgehakt'; end if;
  if p.status = 'gebucht' and p.buchung_id is null then
    raise exception 'Buchung nicht zuzuordnen — bitte unter Material → Buchungen stornieren';
  end if;

  if p.buchung_id is not null and not exists (select 1 from buchung where storno_von = p.buchung_id) then
    perform buchung_stornieren(p.buchung_id, 'Schritt an T-' || lpad(t.id::text, 4, '0') || ' zurückgenommen', p_bearbeiter);
  end if;
  update ticket_position set status = 'reserviert', erledigt_am = null, erledigt_von = null, buchung_id = null
   where id = p.id;
end $$;

-- Fahrer eines Rads wechseln: alte Zuordnung schließen, neue öffnen.
-- p_sportler = null nimmt das Rad nur aus der Zuordnung.
create or replace function rad_zuordnen(p_rad text, p_sportler bigint) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st bigint := recht_arbeiten();
begin
  if not exists (select 1 from rad where id = p_rad and standort_id = v_st) then raise exception 'Unbekanntes Rad: %', p_rad; end if;
  if p_sportler is not null and not exists (select 1 from sportler where id = p_sportler and standort_id = v_st) then
    raise exception 'Unbekannter Sportler';
  end if;
  update zuordnung set gueltig_bis = current_date
   where rad_id = p_rad and gueltig_bis is null;
  if p_sportler is not null then
    insert into zuordnung (rad_id, sportler_id) values (p_rad, p_sportler);
  end if;
end $$;

-- Rechnung festschreiben: offene, abzurechnende Entnahmen eines Sportlers
-- im Zeitraum bekommen eine Rechnungsnummer. Datum und Jahr nach deutscher
-- Zeit, Nummer je Standort ohne Doppelvergabe, Summe genau aus den Posten.
create or replace function rechnung_erstellen(p_sportler bigint, p_von date default null, p_bis date default null)
returns bigint
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st     bigint := recht_rechnen();
  v_heute  date := (now() at time zone 'Europe/Berlin')::date;
  v_von    date := coalesce(p_von, date '2000-01-01');
  v_bis    date := coalesce(p_bis, (now() at time zone 'Europe/Berlin')::date);
  v_jahr   text := to_char((now() at time zone 'Europe/Berlin')::date, 'YYYY');
  v_id     bigint;
  v_nr     text;
  v_summe  numeric;
begin
  if not exists (select 1 from sportler where id = p_sportler and standort_id = v_st) then raise exception 'Unbekannter Sportler'; end if;
  -- Immer nur eine Rechnung je Standort gleichzeitig, damit keine Nummer doppelt vergeben wird.
  perform pg_advisory_xact_lock(hashtext('rechnung_nummer_' || v_st));

  select 'R-' || v_jahr || '-' || lpad((count(*) + 1)::text, 3, '0') into v_nr
    from rechnung where standort_id = v_st and nummer like 'R-' || v_jahr || '-%';

  insert into rechnung (nummer, datum, sportler_id, von, bis, summe, standort_id)
  values (v_nr, v_heute, p_sportler, v_von, v_bis, 0, v_st)
  returning id into v_id;

  with markiert as (
    update buchung b set rechnung_id = v_id
     where b.sportler_id = p_sportler and b.standort_id = v_st and b.art = 'entnahme' and b.abrechnen and b.rechnung_id is null
       and (b.zeit at time zone 'Europe/Berlin')::date between v_von and v_bis
       and not exists (select 1 from buchung s where s.storno_von = b.id)
    returning -b.menge * b.einzelpreis as betrag
  )
  select coalesce(sum(betrag), 0) into v_summe from markiert;

  if v_summe = 0 then raise exception 'Keine offenen Posten im Zeitraum'; end if;

  update rechnung set summe = v_summe where id = v_id;
  return v_id;
end $$;

-- ---------------------------------------------------------------------
--  Inventur-Modus: eine ganze Zählung in einem Schritt buchen.
--  Gebucht wird je Artikel die Differenz zum Systembestand IM MOMENT
--  DES ZÄHLENS (basis). Buchungen, die während der Inventur passieren,
--  bleiben dadurch erhalten.
--  p_zaehlung: [{"code":"B-120","gezaehlt":4,"basis":5}, …]
-- ---------------------------------------------------------------------
create or replace function inventur_buchen(p_ort text, p_zaehlung jsonb, p_bearbeiter text default null,
                                           p_lauf uuid default null)
returns integer
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st     bigint := recht_arbeiten();
  v_z      jsonb;
  v_code   text;
  v_g      numeric;
  v_b      numeric;
  v_ort    lagerort := p_ort;
  v_anzahl integer := 0;
begin
  p_bearbeiter := ich_name();
  if p_lauf is not null then
    perform pg_advisory_xact_lock(hashtext(p_lauf::text));
    select korrekturen into v_anzahl from inventur_lauf where id = p_lauf;
    if found then return v_anzahl; end if;     -- schon gebucht
    v_anzahl := 0;
  end if;

  for v_z in select * from jsonb_array_elements(coalesce(p_zaehlung, '[]'::jsonb)) loop
    v_code := v_z ->> 'code';
    v_g    := (v_z ->> 'gezaehlt')::numeric;
    v_b    := coalesce((v_z ->> 'basis')::numeric, 0);
    if v_g is null or v_g < 0 then raise exception 'Ungültige Zählung für %', v_code; end if;
    if not exists (select 1 from artikel where code = v_code and standort_id = v_st) then raise exception 'Unbekannter Artikel: %', v_code; end if;

    if v_g <> v_b then
      insert into buchung (art, code, menge, ort, notiz, bearbeiter, standort_id)
      values ('korrektur', v_code, v_g - v_b, v_ort,
              'Inventur: gezählt ' || v_g || ', System beim Zählen ' || v_b, p_bearbeiter, v_st);
      v_anzahl := v_anzahl + 1;
    end if;
    insert into zaehlung (code, ort, bearbeiter, standort_id) values (v_code, v_ort, p_bearbeiter, v_st)
    on conflict (code, ort) do update set gezaehlt_am = now(), bearbeiter = excluded.bearbeiter;
  end loop;

  if p_lauf is not null then
    insert into inventur_lauf (id, ort, bearbeiter, gezaehlt, korrekturen, standort_id)
    values (p_lauf, v_ort, p_bearbeiter, jsonb_array_length(coalesce(p_zaehlung, '[]'::jsonb)), v_anzahl, v_st);
  end if;
  return v_anzahl;
end $$;

-- ---------------------------------------------------------------------
--  Fehlbuchung stornieren: Gegenbuchung mit Grund. Umbuchungen und
--  Pauschalen mit Verbrauch werden als Ganzes storniert.
-- ---------------------------------------------------------------------
create or replace function buchung_stornieren(p_buchung bigint, p_grund text, p_bearbeiter text default null)
returns integer
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st     bigint := recht_arbeiten();
  b        buchung;
  z        buchung;
  v_anzahl integer := 0;
begin
  p_bearbeiter := ich_name();
  if coalesce(trim(p_grund), '') = '' then raise exception 'Bitte einen Grund angeben'; end if;
  select * into b from buchung where id = p_buchung and standort_id = v_st for update;
  if not found then raise exception 'Buchung % nicht gefunden', p_buchung; end if;
  if b.art = 'storno' then raise exception 'Eine Storno-Buchung kann nicht storniert werden'; end if;

  for z in
    select * from buchung
     where standort_id = v_st
       and (id = b.id
        or (b.gruppe is not null and gruppe = b.gruppe)
        -- Pauschalen aus der Zeit vor 5.0.0: Verbrauch hat keine Gruppe,
        -- entstand aber in derselben Buchung (gleiche Zeit, gleicher Sportler/Ticket)
        or (b.gruppe is null and b.art = 'entnahme' and art = 'entnahme' and zeit = b.zeit
            and sportler_id is not distinct from b.sportler_id and ticket_id is not distinct from b.ticket_id
            and notiz = 'Verbrauch aus ' || b.code))
     order by id
     for update
  loop
    if z.rechnung_id is not null then
      raise exception 'Steht auf einer Rechnung — erst die Rechnung stornieren';
    end if;
    if exists (select 1 from buchung where storno_von = z.id) then
      raise exception 'Bereits storniert';
    end if;
    insert into buchung (art, code, menge, ort, sportler_id, ticket_id, einzelpreis, abrechnen,
                         gruppe, notiz, bearbeiter, storno_von, standort_id)
    values ('storno', z.code, -z.menge, z.ort, z.sportler_id, z.ticket_id, z.einzelpreis, false,
            z.gruppe, 'Storno: ' || trim(p_grund), p_bearbeiter, z.id, v_st);
    v_anzahl := v_anzahl + 1;
  end loop;
  return v_anzahl;
end $$;

-- ---------------------------------------------------------------------
--  Rechnung stornieren: Nummer und Betrag bleiben stehen, die Posten
--  werden wieder offen und erscheinen in der nächsten Rechnung.
-- ---------------------------------------------------------------------
create or replace function rechnung_stornieren(p_rechnung bigint, p_grund text, p_bearbeiter text default null)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st bigint := recht_rechnen();
  r    rechnung;
begin
  p_bearbeiter := ich_name();
  if coalesce(trim(p_grund), '') = '' then raise exception 'Bitte einen Grund angeben'; end if;
  select * into r from rechnung where id = p_rechnung and standort_id = v_st for update;
  if not found then raise exception 'Rechnung % nicht gefunden', p_rechnung; end if;
  if r.status = 'storniert' then raise exception 'Rechnung ist bereits storniert'; end if;
  if r.status = 'bezahlt' then raise exception 'Rechnung ist als bezahlt markiert — erst auf „offen“ setzen'; end if;

  update buchung set rechnung_id = null where rechnung_id = p_rechnung;
  update rechnung set status = 'storniert', storniert_am = now(), storniert_von = p_bearbeiter,
                      storno_grund = trim(p_grund)
   where id = p_rechnung;
end $$;

-- ---------------------------------------------------------------------
--  Automatische Nummern
--  Jeder Code beginnt mit dem Kürzel des Standorts: SN-B-101 (Artikel und
--  Einzelstücke teilen sich einen Nummernraum, damit ein Scan eindeutig
--  ist), SN-BR-01 (Räder). Buchstabe + Gruppe 1–9 → B-1xx; vergeben wird
--  die höchste vorhandene Nummer + 1 je Standort, Lücken bleiben.
--  Ein Etikett eines anderen Standorts passt nie zu einem Artikel hier.
-- ---------------------------------------------------------------------
create or replace function standort_kuerzel() returns text
language sql stable security definer set search_path = public, pg_temp as $$
  select kuerzel from standort where id = akt_standort();
$$;

-- Gehört der Code zum gewählten Standort (richtiges Kürzel)?
create or replace function eigener_code(p_code text) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(split_part(p_code, '-', 1) = standort_kuerzel(), false);
$$;

-- Kategorie-Buchstabe aus SN-B-101 → B
create or replace function code_buchstabe(p_code text) returns text
language sql immutable as $$
  select substring(p_code from '^[A-Z]{2,3}-([A-Z]{1,3})-[0-9]+$');
$$;

create or replace function naechster_code(p_buchstabe text, p_gruppe integer)
returns text
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_k    text := standort_kuerzel();
  v_b    text := upper(trim(coalesce(p_buchstabe, '')));
  v_max  integer;
  v_n    integer;
begin
  if v_k is null then raise exception 'Kein Zugriff auf diesen Standort'; end if;
  if v_b !~ '^[A-Z]{1,3}$' then raise exception 'Buchstabe: 1 bis 3 Buchstaben A–Z'; end if;
  if p_gruppe is null or p_gruppe < 1 or p_gruppe > 9 then raise exception 'Gruppe: Ziffer 1 bis 9'; end if;

  select max(substring(c from '-([0-9]{3})$')::integer) into v_max
    from (select code as c from artikel union all select nummer from stueck) x
   where c ~ ('^' || v_k || '-' || v_b || '-' || p_gruppe || '[0-9]{2}$');

  v_n := coalesce(v_max + 1, p_gruppe * 100 + 1);
  if v_n > p_gruppe * 100 + 99 then
    raise exception 'Nummernkreis %-%-%xx ist voll', v_k, v_b, p_gruppe;
  end if;
  return v_k || '-' || v_b || '-' || v_n;
end $$;

create or replace function rad_kuerzel(p_typ text) returns text
language sql immutable as $$
  select case p_typ when 'Bahn' then 'BR' when 'Straße' then 'SR' when 'Zeitfahren' then 'ZF'
                    when 'Cross' then 'CX' else 'SO' end;
$$;

create or replace function naechste_rad_id(p_typ text)
returns text
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_k    text := standort_kuerzel() || '-' || rad_kuerzel(p_typ);
  v_max  integer;
begin
  if v_k is null then raise exception 'Kein Zugriff auf diesen Standort'; end if;
  select max(substring(id from '-([0-9]+)$')::integer) into v_max
    from rad where id ~ ('^' || v_k || '-[0-9]+$');
  return v_k || '-' || lpad((coalesce(v_max, 0) + 1)::text, 2, '0');
end $$;

create or replace function artikel_anlegen(p_buchstabe text, p_gruppe integer, p_daten jsonb)
returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st   bigint := recht_arbeiten();
  v_code text;
begin
  perform pg_advisory_xact_lock(hashtext('nummernvergabe'));
  v_code := naechster_code(p_buchstabe, p_gruppe);
  insert into artikel (code, name, einheit, preis, mindestbestand, lieferzeit_tage, art,
                       verbraucht_code, verbrauch_menge, lieferant, bestellnummer, shop_link, aktiv, dauer_min, standort_id)
  values (v_code,
          p_daten ->> 'name',
          coalesce(nullif(p_daten ->> 'einheit', ''), 'Stück'),
          coalesce((p_daten ->> 'preis')::numeric, 0),
          coalesce((p_daten ->> 'mindestbestand')::numeric, 0),
          coalesce((p_daten ->> 'lieferzeit_tage')::integer, 0),
          coalesce(p_daten ->> 'art', 'Stück'),
          nullif(p_daten ->> 'verbraucht_code', ''),
          (p_daten ->> 'verbrauch_menge')::numeric,
          nullif(p_daten ->> 'lieferant', ''),
          nullif(p_daten ->> 'bestellnummer', ''),
          nullif(p_daten ->> 'shop_link', ''),
          coalesce((p_daten ->> 'aktiv')::boolean, true),
          (p_daten ->> 'dauer_min')::integer,
          v_st);
  insert into artikel_tag (code, tag_id)
    select v_code, t.id from tag t
     where t.buchstabe = p_buchstabe and t.standort_id = v_st
       and t.id in (select (x #>> '{}')::bigint from jsonb_array_elements(coalesce(p_daten -> 'tags', '[]'::jsonb)) x);
  return v_code;
end $$;

create or replace function stueck_anlegen(p_buchstabe text, p_gruppe integer, p_daten jsonb)
returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st bigint := recht_arbeiten();
  v_nr text;
begin
  perform pg_advisory_xact_lock(hashtext('nummernvergabe'));
  v_nr := naechster_code(p_buchstabe, p_gruppe);
  insert into stueck (nummer, typ, marke, detail, seriennummer, kaufdatum, wert, notiz, standort_id)
  values (v_nr,
          p_daten ->> 'typ',
          nullif(p_daten ->> 'marke', ''),
          nullif(p_daten ->> 'detail', ''),
          nullif(p_daten ->> 'seriennummer', ''),
          nullif(p_daten ->> 'kaufdatum', '')::date,
          (p_daten ->> 'wert')::numeric,
          nullif(p_daten ->> 'notiz', ''),
          v_st);
  insert into stueck_tag (nummer, tag_id)
    select v_nr, t.id from tag t
     where t.buchstabe = p_buchstabe and t.standort_id = v_st
       and t.id in (select (x #>> '{}')::bigint from jsonb_array_elements(coalesce(p_daten -> 'tags', '[]'::jsonb)) x);
  return v_nr;
end $$;

-- ---------------------------------------------------------------------
--  Serie von Einzelstücken anlegen: mehrere gleiche Teile in einem
--  Schritt, mit aufeinanderfolgenden Nummern. Alles oder nichts.
-- ---------------------------------------------------------------------
create or replace function stueck_serie_anlegen(p_buchstabe text, p_gruppe integer, p_daten jsonb, p_anzahl integer)
returns text[]
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_nummern text[] := '{}';
begin
  perform recht_arbeiten();
  if p_anzahl is null or p_anzahl < 1 or p_anzahl > 50 then
    raise exception 'Anzahl: 1 bis 50';
  end if;
  perform pg_advisory_xact_lock(hashtext('nummernvergabe'));
  for i in 1 .. p_anzahl loop
    v_nummern := v_nummern || stueck_anlegen(p_buchstabe, p_gruppe, p_daten);
  end loop;
  return v_nummern;
end $$;

-- Tags setzen (ganz oder gar nicht)
create or replace function tags_setzen(p_art text, p_schluessel text[], p_tags bigint[])
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st bigint := recht_arbeiten();
begin
  if p_art = 'artikel' then
    delete from artikel_tag where code = any (p_schluessel)
       and code in (select code from artikel where standort_id = v_st);
    insert into artikel_tag (code, tag_id)
      select a.code, t.id from artikel a join tag t
        on t.buchstabe = code_buchstabe(a.code) and t.standort_id = v_st
       where a.code = any (p_schluessel) and a.standort_id = v_st and t.id = any (coalesce(p_tags, '{}'));
  elsif p_art = 'stueck' then
    delete from stueck_tag where nummer = any (p_schluessel)
       and nummer in (select nummer from stueck where standort_id = v_st);
    insert into stueck_tag (nummer, tag_id)
      select s.nummer, t.id from stueck s join tag t
        on t.buchstabe = code_buchstabe(s.nummer) and t.standort_id = v_st
       where s.nummer = any (p_schluessel) and s.standort_id = v_st and t.id = any (coalesce(p_tags, '{}'));
  else
    raise exception 'Unbekannte Art: %', p_art;
  end if;
end $$;

create or replace function tag_zuordnen(p_tag bigint, p_art text, p_mit text[], p_ohne text[])
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st bigint := recht_arbeiten();
  t    tag;
begin
  select * into t from tag where id = p_tag and standort_id = v_st;
  if not found then raise exception 'Unbekannter Tag: %', p_tag; end if;
  if p_art = 'artikel' then
    delete from artikel_tag where tag_id = p_tag and code = any (coalesce(p_ohne, '{}'));
    insert into artikel_tag (code, tag_id)
      select a.code, p_tag from artikel a
       where a.code = any (coalesce(p_mit, '{}')) and a.standort_id = v_st
         and code_buchstabe(a.code) = t.buchstabe
      on conflict do nothing;
  elsif p_art = 'stueck' then
    delete from stueck_tag where tag_id = p_tag and nummer = any (coalesce(p_ohne, '{}'));
    insert into stueck_tag (nummer, tag_id)
      select s.nummer, p_tag from stueck s
       where s.nummer = any (coalesce(p_mit, '{}')) and s.standort_id = v_st
         and code_buchstabe(s.nummer) = t.buchstabe
      on conflict do nothing;
  else
    raise exception 'Unbekannte Art: %', p_art;
  end if;
end $$;

create or replace function rad_anlegen(p_daten jsonb)
returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st  bigint := recht_arbeiten();
  v_id  text;
  v_typ text := coalesce(nullif(p_daten ->> 'typ', ''), 'Bahn');
  v_ei  bigint := (p_daten ->> 'eigentuemer_id')::bigint;
begin
  if v_ei is not null and not exists (select 1 from sportler where id = v_ei and standort_id = v_st) then
    raise exception 'Unbekannter Kostenträger';
  end if;
  perform pg_advisory_xact_lock(hashtext('nummernvergabe'));
  v_id := naechste_rad_id(v_typ);
  insert into rad (id, bezeichnung, typ, marke, rahmennummer, groesse, eigentuemer_id, aktiv, notiz, standort_id)
  values (v_id,
          p_daten ->> 'bezeichnung',
          v_typ,
          nullif(p_daten ->> 'marke', ''),
          nullif(p_daten ->> 'rahmennummer', ''),
          nullif(p_daten ->> 'groesse', ''),
          v_ei,
          coalesce((p_daten ->> 'aktiv')::boolean, true),
          nullif(p_daten ->> 'notiz', ''),
          v_st);
  return v_id;
end $$;

-- ---------------------------------------------------------------------
--  Foto hochladen — mit Kennung vom Gerät, kommt nur einmal an.
--  Sportler: nur an Tickets für ihre Räder.
-- ---------------------------------------------------------------------
create or replace function foto_hochladen(p_ticket bigint, p_thumb text, p_bild text, p_mime text default 'image/jpeg',
                                          p_bearbeiter text default null, p_client_id uuid default null)
returns bigint
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_st  bigint;
  v_id  bigint;
  t     ticket;
begin
  if ich_id() is null then raise exception 'Nicht angemeldet – bitte neu anmelden' using errcode = '28000'; end if;
  v_st := akt_standort();
  if v_st is null then raise exception 'Kein Zugriff auf diesen Standort'; end if;
  p_bearbeiter := ich_name();
  if p_client_id is not null then
    select id into v_id from foto where client_id = p_client_id;
    if found then return v_id; end if;
  end if;
  select * into t from ticket where id = p_ticket and standort_id = v_st and status <> 'storniert';
  if not found then raise exception 'Ticket % nicht gefunden oder storniert', p_ticket; end if;
  if not rolle_in('admin', 'manager', 'trainer')
     and not (meine_rolle() = 'sportler' and (t.fahrer_id = mein_sportler() or t.kostentraeger_id = mein_sportler()
                                              or (t.rad_id is not null and mein_rad(t.rad_id)))) then
    raise exception 'Keine Berechtigung';
  end if;
  insert into foto (ticket_id, client_id, bearbeiter, mime, thumb, bild)
  values (p_ticket, p_client_id, p_bearbeiter, coalesce(p_mime, 'image/jpeg'), p_thumb, p_bild)
  on conflict (client_id) do nothing
  returning id into v_id;
  if v_id is null then
    select id into v_id from foto where client_id = p_client_id;
  end if;
  return v_id;
end $$;

-- Ein Zugang schließt offene Bestellungen des Artikels ab.
create or replace function bestellung_erhalten() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update bestellung set erhalten_am = now() where code = new.code and erhalten_am is null;
  return null;
end $$;

-- Neue Zeilen gehören zum gewählten Standort (Kopfzeile X-Standort).
alter table sportler alter column standort_id set default akt_standort();
alter table kategorie alter column standort_id set default akt_standort();
alter table tag alter column standort_id set default akt_standort();
alter table artikel alter column standort_id set default akt_standort();
alter table rad alter column standort_id set default akt_standort();
alter table stueck alter column standort_id set default akt_standort();
alter table ticket alter column standort_id set default akt_standort();
alter table rechnung alter column standort_id set default akt_standort();
alter table buchung alter column standort_id set default akt_standort();
alter table koffer_soll alter column standort_id set default akt_standort();
alter table termin alter column standort_id set default akt_standort();
alter table zaehlung alter column standort_id set default akt_standort();
alter table inventur_lauf alter column standort_id set default akt_standort();
alter table bestellung alter column standort_id set default akt_standort();

-- Trigger
create trigger buchung_bearbeiter    before insert on buchung    for each row execute function bearbeiter_setzen();
create trigger bestellung_bearbeiter before insert on bestellung for each row execute function bearbeiter_setzen();
create trigger ticket_uebernahme     before update on ticket     for each row execute function ticket_uebernahme();
create trigger artikel_preis         before update on artikel    for each row execute function preis_schutz();

-- ---------------------------------------------------------------------
--  Zugriffsregeln
--  Die App holt sich bei Neon Auth einen anonymen Schlüssel (Rolle
--  anonymous). Was damit erlaubt ist, hängt an der Sitzung (X-Sitzung)
--  und am Standort (X-Standort):
--    S  = Zeile gehört zum gewählten Standort
--    P  = Personal: admin, manager, trainer, geschaeftsstelle (alles lesen)
--    W  = Werkstatt: admin, manager, trainer (buchen, Tickets, Stammdaten)
--    M  = Manager: admin, manager (löschen, Kategorien, Tags, Preise)
--    R  = Rechnungen: admin, manager, geschaeftsstelle
--  Sportler sehen nur, was ihnen zugeordnet ist (ihre Räder, Tickets,
--  Rechnungen, Buchungen) und die Artikel- und Kategorienamen.
--  Buchungen außer Zugängen, Abschließen, Stornieren, Rechnungen und
--  Konten laufen ausschließlich über die Datenbankfunktionen.
-- ---------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array['standort', 'konto', 'konto_rolle', 'einladung', 'sitzung', 'fehlversuch', 'person', 'trainer',
                           'sportler', 'kategorie', 'tag', 'artikel', 'artikel_tag', 'rad', 'zuordnung', 'stueck', 'stueck_tag',
                           'ticket', 'ticket_stueck', 'ticket_position', 'buchung', 'rechnung', 'koffer_soll', 'termin',
                           'zaehlung', 'inventur_lauf', 'foto', 'bestellung'] loop
    execute format('alter table %I enable row level security', t);
  end loop;
end $$;

create policy lesen on standort for select to anonymous
  using (id = (select akt_standort()));
create policy briefkopf on standort for update to anonymous
  using (id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'geschaeftsstelle')))
  with check (id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'geschaeftsstelle')));

create policy lesen on sportler for select to anonymous
  using (standort_id = (select akt_standort())
         and ((select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')) or id = (select mein_sportler())));
create policy anlegen on sportler for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')));
create policy aendern on sportler for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')));

create policy lesen on kategorie for select to anonymous
  using (standort_id = (select akt_standort()));
create policy anlegen on kategorie for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')));
create policy aendern on kategorie for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')));

create policy lesen on tag for select to anonymous
  using (standort_id = (select akt_standort()));
create policy anlegen on tag for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')));
create policy aendern on tag for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')));
create policy loeschen on tag for delete to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')));

create policy lesen on artikel for select to anonymous
  using (standort_id = (select akt_standort()));
create policy anlegen on artikel for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')) and eigener_code(code));
create policy aendern on artikel for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')) and eigener_code(code));

create policy lesen on artikel_tag for select to anonymous
  using (exists (select 1 from artikel a where a.code = artikel_tag.code));
create policy lesen on stueck_tag for select to anonymous
  using (exists (select 1 from stueck s where s.nummer = stueck_tag.nummer));

create policy lesen on rad for select to anonymous
  using (standort_id = (select akt_standort())
         and ((select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')) or mein_rad(id)));
create policy anlegen on rad for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')) and eigener_code(id)
              and (eigentuemer_id is null or exists (select 1 from sportler s where s.id = rad.eigentuemer_id)));
create policy aendern on rad for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')) and eigener_code(id)
              and (eigentuemer_id is null or exists (select 1 from sportler s where s.id = rad.eigentuemer_id)));

create policy lesen on zuordnung for select to anonymous
  using (exists (select 1 from rad r where r.id = zuordnung.rad_id));

create policy lesen on stueck for select to anonymous
  using (standort_id = (select akt_standort())
         and ((select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')) or (rad_id is not null and mein_rad(rad_id))));
create policy anlegen on stueck for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')) and eigener_code(nummer)
              and (rad_id is null or exists (select 1 from rad r where r.id = stueck.rad_id)));
create policy aendern on stueck for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')) and eigener_code(nummer)
              and (rad_id is null or exists (select 1 from rad r where r.id = stueck.rad_id)));
create policy loeschen on stueck for delete to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')));

-- Tickets: nur offene/angenommene ändern; abschließen und stornieren gehen
-- ausschließlich über die Funktionen.
create policy lesen on ticket for select to anonymous
  using (standort_id = (select akt_standort())
         and ((select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle'))
              or fahrer_id = (select mein_sportler()) or kostentraeger_id = (select mein_sportler())
              or (rad_id is not null and mein_rad(rad_id))));
create policy aendern on ticket for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer'))
         and status in ('offen', 'angenommen'))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer'))
              and status in ('offen', 'angenommen')
              and (kostentraeger_id is null or exists (select 1 from sportler s where s.id = ticket.kostentraeger_id)));

create policy lesen on ticket_stueck for select to anonymous
  using (exists (select 1 from ticket t where t.id = ticket_stueck.ticket_id));

-- Reservierungen: nur an offenen Tickets, nur Menge ändern und freigeben.
create policy lesen on ticket_position for select to anonymous
  using (exists (select 1 from ticket t where t.id = ticket_position.ticket_id));
create policy vormerken on ticket_position for insert to anonymous
  with check ((select rolle_in('admin', 'manager', 'trainer')) and status = 'reserviert'
              and exists (select 1 from ticket t where t.id = ticket_position.ticket_id and t.status in ('offen', 'angenommen'))
              and (code is null or exists (select 1 from artikel a where a.code = ticket_position.code)));
create policy aendern on ticket_position for update to anonymous
  using ((select rolle_in('admin', 'manager', 'trainer')) and status = 'reserviert'
         and exists (select 1 from ticket t where t.id = ticket_position.ticket_id and t.status in ('offen', 'angenommen')))
  with check ((select rolle_in('admin', 'manager', 'trainer')) and status in ('reserviert', 'storniert')
              and exists (select 1 from ticket t where t.id = ticket_position.ticket_id and t.status in ('offen', 'angenommen')));

-- Rechnungen: nur zwischen offen und bezahlt wechseln; stornieren nur über die Funktion.
create policy lesen on rechnung for select to anonymous
  using (standort_id = (select akt_standort())
         and ((select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')) or sportler_id = (select mein_sportler())));
create policy aendern on rechnung for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'geschaeftsstelle'))
         and status in ('offen', 'bezahlt'))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'geschaeftsstelle'))
              and status in ('offen', 'bezahlt'));

-- Journal: lesen; von außen nur Zugänge mit positiver Menge.
create policy lesen on buchung for select to anonymous
  using (standort_id = (select akt_standort())
         and ((select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')) or sportler_id = (select mein_sportler())));
create policy zugang on buchung for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer'))
              and art = 'zugang' and menge > 0
              and exists (select 1 from artikel a where a.code = buchung.code));

create policy lesen on koffer_soll for select to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')));
create policy anlegen on koffer_soll for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer'))
              and exists (select 1 from artikel a where a.code = koffer_soll.code));
create policy aendern on koffer_soll for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')));
create policy loeschen on koffer_soll for delete to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')));

create policy lesen on termin for select to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')));
create policy anlegen on termin for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')));
create policy aendern on termin for update to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')))
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')));
create policy loeschen on termin for delete to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager')));

-- Zählstand lesen; geschrieben wird er nur von den Inventur-Funktionen.
create policy lesen on zaehlung for select to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')));
create policy lesen on inventur_lauf for select to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')));

-- Bestellungen: lesen, als bestellt markieren, offene zurücknehmen.
create policy lesen on bestellung for select to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer', 'geschaeftsstelle')));
create policy bestellen on bestellung for insert to anonymous
  with check (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer'))
              and erhalten_am is null and exists (select 1 from artikel a where a.code = bestellung.code));
create policy zuruecknehmen on bestellung for delete to anonymous
  using (standort_id = (select akt_standort()) and (select rolle_in('admin', 'manager', 'trainer')) and erhalten_am is null);

-- Fotos: lesen wie das Ticket; hochladen über foto_hochladen; löschen
-- (nur Manager) an offenen Tickets.
create policy lesen on foto for select to anonymous
  using (exists (select 1 from ticket t where t.id = foto.ticket_id));
create policy loeschen on foto for delete to anonymous
  using ((select rolle_in('admin', 'manager'))
         and exists (select 1 from ticket t where t.id = foto.ticket_id and t.status in ('offen', 'angenommen')));

-- ---------------------------------------------------------------------
--  Rechte der Rolle anonymous
--  Konten, Sitzungen, Einladungen, Namensliste (person) und die alte
--  Tabelle trainer sind von außen nicht lesbar.
-- ---------------------------------------------------------------------
revoke all on all tables in schema public from anonymous;
grant usage on schema public to anonymous;
grant select on standort, sportler, kategorie, tag, artikel, artikel_tag, rad, zuordnung, stueck, stueck_tag,
                ticket, ticket_stueck, ticket_position, rechnung, buchung, koffer_soll, termin, zaehlung,
                inventur_lauf, bestellung, foto, v_bestand, v_rad, v_koffer, v_offene_posten to anonymous;
grant update (name, rg_empfaenger, rg_absender, rg_kopf, rg_fuss, rg_text, iban, bic, bank,
              zahlungsziel_tage, logo, fuss_logo) on standort to anonymous;
grant insert on stueck, termin, koffer_soll, sportler, rad, artikel, tag, kategorie to anonymous;
grant insert (art, code, menge, ort, notiz, bearbeiter) on buchung to anonymous;
grant insert (ticket_id, code, menge, titel, dauer_min) on ticket_position to anonymous;
grant insert (code, menge, bearbeiter) on bestellung to anonymous;
grant update on stueck, koffer_soll, sportler, rad, artikel, tag, kategorie to anonymous;
grant update (soll_fertig, naechstmoeglich, anlass, aufwand, fahrbereit, arbeitsort,
              kostentraeger_id, status, uebernommen_von) on ticket to anonymous;
grant update (menge, status, titel, dauer_min) on ticket_position to anonymous;
grant update (status) on rechnung to anonymous;
grant delete on termin, koffer_soll, foto, stueck, bestellung, tag to anonymous;
revoke all on all sequences in schema public from anonymous;
grant usage, select on all sequences in schema public to anonymous;

revoke execute on all functions in schema public from public, anonymous;
grant execute on function
  -- Hilfen, die die Zugriffsregeln und Spaltenvorgaben aufrufen
  kopfzeile(text), token_hash(text), ich_id(), ich_name(), ist_admin(), akt_standort(), meine_rolle(),
  rolle_in(text[]), mein_sportler(), mein_rad(text), standort_kuerzel(), eigener_code(text), code_buchstabe(text),
  -- Anmelden und Konto
  standorte_liste(), anmelde_liste(bigint),
  anmelden(bigint, text, bigint, text, text, boolean),
  einladung_pruefen(text), einladung_einloesen(text, text, text, boolean),
  ich(), abmelden(), pin_aendern(text, text),
  konten_liste(), konto_anlegen(text, text, bigint), konto_neuer_code(bigint),
  konto_aendern(bigint, text, text, boolean), sportler_zugang(bigint), standort_anlegen(text, text),
  -- Werkstatt
  rad_zuordnen(text, bigint),
  material_ausgeben(text, numeric, text, bigint, bigint, text, text),
  umbuchen(text, numeric, text, text, text, text),
  inventur(text, text, numeric, text),
  inventur_buchen(text, jsonb, text, uuid),
  ticket_anlegen(text, text, boolean, date, boolean, text, text, jsonb, text, uuid, text, text[]),
  ticket_abschliessen(bigint, text),
  ticket_stuecke_aendern(bigint, text[], text[]),
  ticket_stornieren(bigint, text),
  position_erledigen(bigint, text),
  position_zuruecknehmen(bigint, text),
  rechnung_erstellen(bigint, date, date),
  rechnung_stornieren(bigint, text, text),
  buchung_stornieren(bigint, text, text),
  naechster_code(text, integer),
  rad_kuerzel(text),
  naechste_rad_id(text),
  artikel_anlegen(text, integer, jsonb),
  stueck_anlegen(text, integer, jsonb),
  stueck_serie_anlegen(text, integer, jsonb, integer),
  tags_setzen(text, text[], bigint[]),
  tag_zuordnen(bigint, text, text[], text[]),
  rad_anlegen(jsonb),
  foto_hochladen(bigint, text, text, text, text, uuid)
to anonymous;

-- Gesamt-Admin (alle Standorte) und Werkstatt-Manager in Schwerin.
-- Den Einrichtungscode erzeugt die Zeile ganz unten (nach commit).
insert into konto (name, gesamt_admin) values ('Hauke', true);
insert into konto_rolle (konto_id, standort_id, rolle)
  select k.id, s.id, 'manager' from konto k, standort s where k.name = 'Hauke' and s.name = 'RSZ Schwerin';

commit;

-- Einrichtungscode für den Gesamt-Admin (gilt 7 Tage, einmal).
-- In der App „Code“ wählen und eine PIN (6 Ziffern) setzen.
select notfall_code('Hauke') as einrichtungscode;
